-- V1: identity and accounts
-- Tables: CUSTOMERS, APP_USERS, ACCOUNTS, ACCOUNT_BALANCES
-- Design: docs/milestone-2-erd.md (approved). IDs are RAW(16), generated by the
-- application (UUIDv7). Money is NUMBER(19,4). Timestamps are TIMESTAMP WITH TIME ZONE.
-- Oracle DDL auto-commits: if this script fails part-way, repair forward, do not edit it.

CREATE TABLE CUSTOMERS (
    CUSTOMER_ID   RAW(16)                     NOT NULL,
    NAME          VARCHAR2(200 CHAR)          NOT NULL,
    STATUS        VARCHAR2(20)                NOT NULL,
    CREATED_AT    TIMESTAMP WITH TIME ZONE    DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT    TIMESTAMP WITH TIME ZONE    DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_CUSTOMERS        PRIMARY KEY (CUSTOMER_ID),
    CONSTRAINT CK_CUSTOMERS_STATUS CHECK (STATUS IN ('ACTIVE', 'SUSPENDED', 'CLOSED'))
);

CREATE TABLE APP_USERS (
    USER_ID       RAW(16)                     NOT NULL,
    CUSTOMER_ID   RAW(16),
    IDP_SUBJECT   VARCHAR2(255)               NOT NULL,
    ROLE          VARCHAR2(20)                NOT NULL,
    STATUS        VARCHAR2(20)                NOT NULL,
    CREATED_AT    TIMESTAMP WITH TIME ZONE    DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT    TIMESTAMP WITH TIME ZONE    DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_APP_USERS          PRIMARY KEY (USER_ID),
    CONSTRAINT UK_APP_USERS_SUBJECT  UNIQUE (IDP_SUBJECT),
    CONSTRAINT FK_APP_USERS_CUSTOMER FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMERS (CUSTOMER_ID),
    CONSTRAINT CK_APP_USERS_ROLE     CHECK (ROLE IN ('CUSTOMER', 'OPERATOR')),
    CONSTRAINT CK_APP_USERS_STATUS   CHECK (STATUS IN ('ACTIVE', 'DISABLED')),
    -- Customers belong to a customer; operators (support staff) belong to none.
    CONSTRAINT CK_APP_USERS_ROLE_CUST CHECK (
        (ROLE = 'CUSTOMER' AND CUSTOMER_ID IS NOT NULL)
        OR (ROLE = 'OPERATOR' AND CUSTOMER_ID IS NULL)
    )
);

CREATE TABLE ACCOUNTS (
    ACCOUNT_ID       RAW(16)                  NOT NULL,
    ACCOUNT_NUMBER   VARCHAR2(32)             NOT NULL,
    CUSTOMER_ID      RAW(16)                  NOT NULL,
    CURRENCY         VARCHAR2(3)              NOT NULL,
    STATUS           VARCHAR2(20)             NOT NULL,
    CREATED_AT       TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    UPDATED_AT       TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_ACCOUNTS           PRIMARY KEY (ACCOUNT_ID),
    CONSTRAINT UK_ACCOUNTS_NUMBER    UNIQUE (ACCOUNT_NUMBER),
    CONSTRAINT FK_ACCOUNTS_CUSTOMER  FOREIGN KEY (CUSTOMER_ID) REFERENCES CUSTOMERS (CUSTOMER_ID),
    -- ACCOUNT_NUMBER is the API accountId; same pattern as the OpenAPI contract.
    CONSTRAINT CK_ACCOUNTS_NUMBER_FMT CHECK (REGEXP_LIKE(ACCOUNT_NUMBER, '^[A-Za-z0-9_-]{1,32}$')),
    CONSTRAINT CK_ACCOUNTS_CURRENCY  CHECK (CURRENCY IN ('USD')),
    CONSTRAINT CK_ACCOUNTS_STATUS    CHECK (STATUS IN ('ACTIVE', 'FROZEN', 'CLOSED'))
);

CREATE TABLE ACCOUNT_BALANCES (
    ACCOUNT_ID         RAW(16)                  NOT NULL,
    AVAILABLE_BALANCE  NUMBER(19,4)             NOT NULL,
    LEDGER_BALANCE     NUMBER(19,4)             NOT NULL,
    VERSION            NUMBER(19)               DEFAULT 0 NOT NULL,
    UPDATED_AT         TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT PK_ACCOUNT_BALANCES     PRIMARY KEY (ACCOUNT_ID),
    CONSTRAINT FK_ACCT_BAL_ACCOUNT     FOREIGN KEY (ACCOUNT_ID) REFERENCES ACCOUNTS (ACCOUNT_ID),
    -- No overdraft in V1.
    CONSTRAINT CK_ACCT_BAL_AVAIL       CHECK (AVAILABLE_BALANCE >= 0),
    CONSTRAINT CK_ACCT_BAL_LEDGER      CHECK (LEDGER_BALANCE >= 0),
    -- V1 has no holds (posting is synchronous and a PENDING_REVIEW transfer reserves no
    -- funds), so the two balances are always equal. Both columns are kept so the API shape
    -- survives a later hold model; the posting service must update them together.
    -- Introducing holds requires a hold table and accounting rules plus an additive
    -- migration that replaces this constraint (see docs/milestone-2-erd.md, ACCOUNT_BALANCES).
    CONSTRAINT CK_ACCT_BAL_EQUAL        CHECK (AVAILABLE_BALANCE = LEDGER_BALANCE)
);
